insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
values
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 1, $txt$N1.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Say the number sequence, 0 to 100, by: 1s forward and backward between any two given numbers; 2s to 20, forward starting at 0; 5s and 10s to 100, forward starting at 0.$txt$, $txt${"processes":"C, CN, V, ME","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=145&oc=78065$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 1, $txt$N1.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Recognize, at a glance, and name familiar arrangements of 1 to 10 objects, dots, and pictures.$txt$, $txt${"processes":"C, CN, V, ME","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=145&oc=78074$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 1, $txt$N1.3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of counting by: indicating that the last number said identifies "how many"; showing that any set has only one count using the counting on strategy; using parts or equal groups to count sets.$txt$, $txt${"processes":"C, CN, ME, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=145&oc=78078$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 1, $txt$N1.4$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Represent and describe whole numbers to 20 concretely, pictorially, and symbolically.$txt$, $txt${"processes":"C, CN, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=145&oc=78085$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 1, $txt$N1.5$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Compare sets containing up to 20 elements to solve problems using: referents (known quantity); one-to-one correspondence.$txt$, $txt${"processes":"C, CN, ME, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=145&oc=78091$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 1, $txt$N1.6$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Estimate quantities to 20 by using referents.$txt$, $txt${"processes":"C, PS, ME, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=145&oc=78098$txt$, 6, false, $txt$2026-10-17$txt$::date),
