  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 1, $txt$SS1.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of measurement as a process of comparing by: identifying attributes that can be compared; ordering objects; making statements of comparison; filling, covering, or matching.$txt$, $txt${"processes":"C, CN, ME, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=145&oc=78145$txt$, 15, false, $txt$2026-10-17$txt$::date),
