  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 2, $txt$N2.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of addition (limited to 1 and 2-digit numerals) with answers to 100 and the corresponding subtraction by: representing strategies for adding and subtracting concretely, pictorially, and symbolically; creating and solving problems involving addition and subtraction; estimating; using personal strategies for adding and subtracting with and without the support of manipulatives; analyzing the effect of adding or subtracting zero; analyzing the effect of the ordering of the quantities (addends, minuends, and subtrahends) in addition and subtraction statements.$txt$, $txt${"processes":"C, CN, ME, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=146&oc=78333$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$P$txt$), 2, $txt$P2.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of repeating patterns (three to five elements) by: describing; representing patterns in alternate modes; extending; comparing; creating patterns using manipulatives, pictures, sounds, and actions.$txt$, $txt${"processes":"C, CN, ME, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=146&oc=78342$txt$, 3, false, $txt$2026-10-17$txt$::date),
