  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 2, $txt$SS2.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of non-standard units for linear measurement by: describing the choice and appropriate use of non-standard units; estimating; measuring; comparing and analyzing measurements.$txt$, $txt${"processes":"C, CN, ME, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=146&oc=78367$txt$, 6, false, $txt$2026-10-17$txt$::date),
