  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 3, $txt$N3.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of addition of whole numbers with answers to 1000 and their corresponding subtractions (limited to 1, 2, and 3-digit numerals) including: representing strategies for adding and subtracting concretely, pictorially, and symbolically; solving situational questions involving addition and subtraction; estimating using personal strategies for adding and subtracting.$txt$, $txt${"processes":"CN, ME, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=147&oc=78183$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 3, $txt$N3.3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of multiplication to 5 x 5 and the corresponding division statements including: representing and explaining using repeated addition or subtraction, equal grouping, and arrays; creating and solving situational questions; modelling processes using concrete, physical, and visual representations, and recording the process symbolically; relating multiplication and division.; Note: The focus of this outcome is for the students to become familiar with multiplication and division and strategies for mentally determining products and quotients. It is not intended that students memorize the basic facts.$txt$, $txt${"processes":"C, CN, PS, R","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=147&oc=78196$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 3, $txt$N3.4$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of fractions concretely, pictorially, physically, and orally including: representing; observing and describing situations; comparing; relating to quantity.$txt$, $txt${"processes":"C, CN, R","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=147&oc=78208$txt$, 4, false, $txt$2026-10-17$txt$::date),
