  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 6, $txt$SS6.4$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of the first quadrant of the Cartesian plane and ordered pairs with whole number coordinates.$txt$, $txt${"processes":"C, CN, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=150&oc=78683$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 6, $txt$SS6.5$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of single, and combinations of, transformations of 2-D shapes (with and without the use of technology) including: identifying; describing; performing.$txt$, $txt${"processes":"C, CN, R, T, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=150&oc=78691$txt$, 17, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SP$txt$), 6, $txt$SP6.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Extend understanding of data analysis to include: line graphs; graphs of discrete data; data collection through questionnaires, experiments, databases, and electronic media; interpolation and extrapolation.$txt$, $txt${"processes":"C, CN, PS, R, V, T","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=150&oc=78706$txt$, 18, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SP$txt$), 6, $txt$SP6.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of probability by: determining sample space; differentiating between experimental and theoretical probability; determining the theoretical probability; determining the experimental probability; comparing experimental and theoretical probabilities.$txt$, $txt${"processes":"C, PS, R, T","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=150&oc=78717$txt$, 19, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 7, $txt$N7.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of division through the development and application of divisibility strategies for 2, 3, 4, 5, 6, 8, 9, and 10, and through an analysis of division involving zero.$txt$, $txt${"processes":"C, CN, ME,R","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78728$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 7, $txt$N7.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Expand and demonstrate understanding of the addition, subtraction, multiplication, and division of decimals to greater numbers of decimal places, and the order of operations.$txt$, $txt${"processes":"C, CN, ME, PS, R, T","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78734$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 7, $txt$N7.3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of the relationships between positive decimals, positive fractions (including mixed numbers, proper fractions and improper fractions), and whole numbers.$txt$, $txt${"processes":"C, CN, ME, R, T","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78744$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 7, $txt$N7.4$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Expand and demonstrate an understanding of percent to include fractional percents between 1% and 100%.$txt$, $txt${"processes":"C, PS, R","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78758$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 7, $txt$N7.5$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Develop and demonstrate an understanding of adding and subtracting positive fractions and mixed numbers, with like and unlike denominators, concretely, pictorially, and symbolically (limited to positive sums and differences).$txt$, $txt${"processes":"C, CN, ME, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78766$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 7, $txt$N7.6$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of addition and subtraction of integers, concretely, pictorially, and symbolically.$txt$, $txt${"processes":"C, CN, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78777$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$P$txt$), 7, $txt$P7.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of the relationships between oral and written patterns, graphs and linear relations.$txt$, $txt${"processes":"C, CN, R","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78786$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$P$txt$), 7, $txt$P7.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of equations and expressions by: distinguishing between equations and expressions; evaluating expressions; verifying solutions to equations.$txt$, $txt${"processes":"C, CN, ME","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78800$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$P$txt$), 7, $txt$P7.3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of one- and two-step linear equations of the form ax/b + c = d (where a, b, c, and d are whole numbers, c ≤ d and b ≠ 0) by modeling the solution of the equations concretely, pictorially, physically, and symbolically and explaining the solution in terms of the preservation of equality.$txt$, $txt${"processes":"C, CN, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78805$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$P$txt$), 7, $txt$P7.4$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of linear equations of the form x + a = b (where a and b are integers) by modeling problems as a linear equation and solving the problems concretely, pictorially, and symbolically.$txt$, $txt${"processes":"C, CN, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78816$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 7, $txt$SS7.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of circles including circumference and central angles.$txt$, $txt${"processes":"C, CN, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78820$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 7, $txt$SS7.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Develop and apply formulas for determining the area of: triangles; parallelograms; circles.$txt$, $txt${"processes":"CN, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78833$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 7, $txt$SS7.3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of 2-D relationships involving lines and angles.$txt$, $txt${"processes":"CN, R, V, T","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78842$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 7, $txt$SS7.4$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of the Cartesian plane and ordered pairs with integral coordinates.$txt$, $txt${"processes":"C, CN, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78853$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 7, $txt$SS7.5$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Expand and demonstrate an understanding of transformations (translations, rotations, and reflections) of 2-D shapes in all four quadrants of the Cartesian plane.$txt$, $txt${"processes":"CN, PS, T, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78860$txt$, 15, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SP$txt$), 7, $txt$SP7.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of the measures of central tendency and range for sets of data.$txt$, $txt${"processes":"C, CN, PS, R, T","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78869$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SP$txt$), 7, $txt$SP7.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of circle graphs.$txt$, $txt${"processes":"C, CN, PS, R, T","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78880$txt$, 17, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SP$txt$), 7, $txt$SP7.3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of theoretical and experimental probabilities for two independent events where the combined sample space has 36 or fewer elements.$txt$, $txt${"processes":"C, ME, PS, R, T","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=151&oc=78887$txt$, 18, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 8, $txt$N8.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of the square and principle square root of whole numbers concretely or pictorially and symbolically.$txt$, $txt${"processes":"CN, ME, R, T, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=152&oc=110728$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 8, $txt$N8.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Expand and demonstrate understanding of percents greater than or equal to 0% (including fractional and decimal percents) concretely, pictorially, and symbolically.$txt$, $txt${"processes":"CN, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=152&oc=110738$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 8, $txt$N8.3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of rates, ratios, and proportional reasoning concretely, pictorially, and symbolically.$txt$, $txt${"processes":"C, CN, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=152&oc=110749$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 8, $txt$N8.4$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of multiplying and dividing positive fractions and mixed numbers, concretely, pictorially, and symbolically.$txt$, $txt${"processes":"C, CN, ME, PS","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=152&oc=110758$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$N$txt$), 8, $txt$N8.5$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of multiplication and division of integers concretely, pictorially, and symbolically.$txt$, $txt${"processes":"C, CN, PS, R, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=152&oc=110775$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$P$txt$), 8, $txt$P8.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of linear relations concretely, pictorially (including graphs), physically, and symbolically.$txt$, $txt${"processes":"CN, ME, PS, R, T, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=152&oc=110785$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$P$txt$), 8, $txt$P8.2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Model and solve problems using linear equations of the form: $ax = b$; $x/a = b, a ≠ 0$; $ax + b = c$; $x/a + b = c, a ≠ 0$; $a(x + b) = c$; concretely, pictorially, and symbolically, where a, b, and c are integers.$txt$, $txt${"processes":"C, CN, PS, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=152&oc=110794$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$SK-MATH-1-8$txt$) and code = $txt$SS$txt$), 8, $txt$SS8.1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate understanding of the Pythagorean Theorem concretely or pictorially and symbolically and by solving problems.$txt$, $txt${"processes":"CN, PS, R, T, V","note":"List items from the official page are joined with \"; \". Process tags moved to processes."}$txt$::jsonb, $txt$https://curriculum.gov.sk.ca/CurriculumOutcomeContent?id=152&oc=110806$txt$, 8, false, $txt$2026-10-17$txt$::date);
